def fair(r):  # rank 1 ~ $85, total ~ $2,700 across 117 spots
    return max(1, round(0.97 * 88 * math.exp(-(r - 1) / 32)))

rows = []
for i, s in enumerate(RANKS, 1):
    name, team = s.rsplit(" ", 1)
    tag, note = TAGS.get(name, ("", ""))
    f = fair(i)
    mx = round(f * 1.12) if tag == "T" else (f if tag == "V" else max(1, round(f * 0.75)) if tag == "A" else f)
    if tag == "T" and f <= 2: mx = 3  # late targets: worth $3 to secure
    rows.append(dict(r=i, n=name, t=team, f=f, m=mx, g=tag, x=note))
for s, tag, note in EXTRA:
    name, team = s.rsplit(" ", 1)
    rows.append(dict(r="-", n=name, t=team, f=1, m=1 if tag == "A" else 2, g=tag, x=note))

print("top-117 total:", sum(r["f"] for r in rows[:117]))
out = pathlib.Path(__file__).with_name("players.json")
out.write_text(json.dumps(rows))
